const prev = $input.first().json;
const timestamp = Date.now().toString();
const body = JSON.stringify({ phone: prev.phone });
const payload = timestamp + '.' + body;
const secret = $env.WHATSAPP_HMAC_SECRET;
const signature = hmacSha256(secret, payload);
return [{ json: { ...prev, hmacTimestamp: timestamp, hmacSignature: signature } }];

const prev = $input.first().json;
// _no_children sentinel — pass through
if (prev._no_children) return [{ json: prev }];
const grades = prev.exams || [];
const studentName = prev.student_name || 'Your child';
const className = prev.class_name || prev.class || '';

if (!Array.isArray(grades) || !grades.length) {
  const msg = prev.message || prev.error || null;
  const text = msg
    ? '⚠️ ' + msg
    : '📊 No exam results available yet for ' + studentName + '.';
  return [{ json: { ...prev, responseText: text } }];
}

let text = '📊 *' + studentName + (className ? ' — ' + className : '') + '*\n\n';
grades.forEach(exam => {
  text += '*' + exam.exam_name + '*\n';
  (exam.marks || []).forEach(m => {
    text += m.subject + ': ' + m.score + '% (' + m.grade + ')\n';
  });
  if (exam.average != null) text += 'Overall: ' + exam.average + '%';
  if (exam.position)        text += ' | Position: ' + exam.position;
  text += '\n\n';
});
return [{ json: { ...prev, responseText: text.trim() } }];

const prev = $input.first().json;
if (prev._no_children) return [{ json: prev }];
const studentName = prev.student_name || 'Your child';
const currency    = prev.currency    || 'UGX';
const totalFees   = prev.total_fees;

if (totalFees == null || prev.error || prev.message?.toLowerCase().includes('error')) {
  return [{ json: { ...prev, responseText: '⚠️ Could not fetch fee balance for ' + studentName + '. Please try again.' } }];
}

let text = '💰 *' + studentName + ''s Fee Balance*\n';
text += 'Balance due: ' + currency + ' ' + totalFees + '\n\n';
(prev.fee_breakdown || []).forEach(f => {
  text += '• ' + f.name + ': ' + currency + ' ' + f.amount + '\n';
});
if (parseFloat(totalFees) > 0) text += '\nReply *PAY* for payment instructions.';
return [{ json: { ...prev, responseText: text } }];

const prev = $input.first().json;
if (prev._no_children) return [{ json: prev }];
const studentName = prev.student_name || 'Your child';

if (prev.present == null || prev.error) {
  return [{ json: { ...prev, responseText: '⚠️ Could not fetch attendance for ' + studentName + '. Please try again.' } }];
}

let text = '📅 *' + studentName + ''s Attendance*\n';
text += 'Present: ' + prev.present + ' days\n';
text += 'Absent:  ' + prev.absent  + ' days\n';
text += 'Late:    ' + prev.late    + ' days\n';
text += 'Rate:    ' + (prev.attendance_rate || 'N/A') + '\nThis term\n';
if ((prev.recent_absences || []).length) {
  text += '\nRecent absences:\n';
  prev.recent_absences.forEach(a => { text += '• ' + a.date + ': ' + a.status + '\n'; });
}
return [{ json: { ...prev, responseText: text } }];

const prev = $input.first().json;
const events = (prev.events || []).slice(0, 5);

if (prev.error || (!events.length && prev.message)) {
  return [{ json: { ...prev, responseText: '⚠️ Could not fetch events. Please try again.' } }];
}
if (!events.length) {
  return [{ json: { ...prev, responseText: '📅 No upcoming events at the moment.' } }];
}

let text = '📅 *Upcoming Events*\n\n';
events.forEach((e, i) => {
  text += '*' + (i+1) + '. ' + e.title + '*\n';
  text += '📆 ' + e.start_date;
  if (e.end_date && e.end_date !== e.start_date) text += ' — ' + e.end_date;
  text += '\n';
  if (e.time)  text += '🕐 ' + e.time  + '\n';
  if (e.venue) text += '📍 ' + e.venue + '\n';
  text += '\n';
});
return [{ json: { ...prev, responseText: text.trim() } }];

const prev = $input.first().json;
const response = prev.text || prev.output || prev.answer || prev.message || '';

if (!response || prev.error) {
  return [{ json: { ...prev, responseText: "I couldn't find that. Try: *grades*, *fees*, *attendance*, or *events*." } }];
}
return [{ json: { ...prev, responseText: response } }];

