const prev = $input.first().json;
const timestamp = Date.now().toString();
const secret = $env.WHATSAPP_HMAC_SECRET;
const signature = hmacSha256(secret, timestamp + '.');
return [{ json: { ...prev, hmacTimestamp: timestamp, hmacSignature: signature } }];

const items = $input.all();
// If no-children sentinel, pass through as-is
if (items[0]?.json?._no_children) return [items[0]];
// If single child, pass through
if (items.length === 1) return [items[0]];
// Multiple children: join responses
const combined = items
  .map(i => i.json.responseText || '')
  .filter(Boolean)
  .join('\n\n───────────\n\n');
return [{ json: { ...items[0].json, responseText: combined } }];

const data = $input.first().json;
const children = data.children || [];
if (!children.length) {
  return [{ json: { ...data, _no_children: true,
    responseText: '⚠️ No students are linked to your account yet. Ask your school admin to register you.' } }];
}
return children.map(child => ({ json: {
  ...data,
  student_id: child.student_id,
  student_name: child.name || child.student_name || ('Student ' + child.student_id),
  _no_children: false
}}));

